// DialError is an error that specifically occurs
// in a call to Dial or DialContext.
type DialError struct{ error }

// NewDialError wraps err as a DialError, so that transports
// outside this package can mark dial failures as safe to retry.
func NewDialError(err error) DialError {
	return DialError{err}
}
